#include <SoftwareSerial.h>

// Bluetooth RC Car
// Drives a 2-motor chassis from single-character Bluetooth commands:
// F = forward, B = backward, L = left, R = right, S = stop.

SoftwareSerial bluetooth(10, 11); // RX, TX

const int IN1 = 2, IN2 = 3; // left motor
const int IN3 = 4, IN4 = 5; // right motor
const int ENA = 6, ENB = 9; // speed (PWM)

const int SPEED = 180; // 0-255

void setup() {
  bluetooth.begin(9600); // HC-05's default baud rate

  pinMode(IN1, OUTPUT); pinMode(IN2, OUTPUT);
  pinMode(IN3, OUTPUT); pinMode(IN4, OUTPUT);
  pinMode(ENA, OUTPUT); pinMode(ENB, OUTPUT);

  stopMotors();
}

void loop() {
  if (bluetooth.available()) {
    char command = bluetooth.read();

    switch (command) {
      case 'F': driveForward(); break;
      case 'B': driveBackward(); break;
      case 'L': pivotLeft();    break;
      case 'R': pivotRight();   break;
      case 'S': stopMotors();   break;
    }
  }
}

void driveForward() {
  digitalWrite(IN1, HIGH); digitalWrite(IN2, LOW);
  digitalWrite(IN3, HIGH); digitalWrite(IN4, LOW);
  analogWrite(ENA, SPEED); analogWrite(ENB, SPEED);
}

void driveBackward() {
  digitalWrite(IN1, LOW); digitalWrite(IN2, HIGH);
  digitalWrite(IN3, LOW); digitalWrite(IN4, HIGH);
  analogWrite(ENA, SPEED); analogWrite(ENB, SPEED);
}

void pivotLeft() {
  digitalWrite(IN1, LOW); digitalWrite(IN2, HIGH);
  digitalWrite(IN3, HIGH); digitalWrite(IN4, LOW);
  analogWrite(ENA, SPEED); analogWrite(ENB, SPEED);
}

void pivotRight() {
  digitalWrite(IN1, HIGH); digitalWrite(IN2, LOW);
  digitalWrite(IN3, LOW); digitalWrite(IN4, HIGH);
  analogWrite(ENA, SPEED); analogWrite(ENB, SPEED);
}

void stopMotors() {
  analogWrite(ENA, 0);
  analogWrite(ENB, 0);
}
